"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0878-01-01:0":{"b": ["Bitka kod Edingtona (Ethandun) i Wedmorski mir: Alfred pobjeđuje Dance (Guthruma)", "bb82711f"], "d": ["Nakon iznenadnog danskog prepada na Chippenham u januaru 878. Alfred se sa šačicom ljudi sakrio; vojske su se sastale kod Edingtona u Wiltshireu. Nakon Wedmorskog mira (878) Danci su se povukli iz Wessexa; sjeveroistočna polovina, uključujući London, ostala je Dancima, ali 'plima se okrenula'.", "4f02f617"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0878-05-21:0":{"b": ["Arapi su zauzeli Sirakuzu", "0ad38c19"], "d": ["Aglabidi su nakon duge opsade 21. maja 878. zauzeli Sirakuzu, glavno bizantsko središte Sicilije; ostrvo je stvarno počelo izlaziti iz bizantskih ruku.", "3c2d97da"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0886-01-01:0":{"b": ["Alfred uzima London od Danaca; mir između Alfreda i Guthruma mijenja granice u Alfredovu korist", "32d8daf9"], "d": ["Alfred je, na kraju mjera protiv pobunjenih Danaca, 885. ili 886. zauzeo London; između Alfreda i Guthruma sklopljen je mir koji je wedmorske granice promijenio u Alfredovu korist.", "01209a4c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0893-01-01:0":{"b": ["U doba Alfonsa III naseljena je Zamora.", "78edf65c"], "d": ["U doba Alfonsa III naseljena je Zamora.", "78edf65c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0893-03-23:0":{"b": ["Samanidski emir Ismail b. Ahmed zauzeo je Talas (Taraz); Samanidi su na istoku dosegli najšire granice", "a25f7598"], "d": ["Ismail b. Ahmed, radi zaštite Maveraunnehra od upada nemuslimanskih Turaka, poveo je pohod sve do Taraza (Talasa) i zauzeo grad; većina tamošnjih turskih emira i dihkana primila je islam, a Ogulčak, koji je izgubio Talas, središte Istočnih Karahanida, prenio je prijestolnicu u Kašgar.", "8bf208a3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0903-01-01:0":{"b": ["Karmati su zauzeli Hamu, Homs, Maaret en-Numan i Baalbek; poslane tulunidske jedinice su poražene (290/903).", "291ecf32"], "d": ["Karmati su zauzeli Hamu, Homs, Maaret en-Numan i Baalbek; poslane tulunidske jedinice su poražene (290/903).", "291ecf32"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0911-01-01:0":{"b": ["Ujgurska vojska iz Kan-choua zauzela je Tun-huang", "36ec7038"], "d": ["Tun-huang, središte autonomnog kraljevstva koje je 905. uspostavio kineski zapovjednik, 911. zauzela je ujgurska vojska pod zapovjedništvom tegina; pobjeda je povećala ugled Ujgura iz Kan-choua kod Kineza.", "3bffe840"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0914-01-01:0":{"b": ["Simeon je zauzeo Edirne", "fe0efa60"], "d": ["Bugarski car Simeon 914. zauzeo je Hadrijanopolj (Edirne); grad je dugo bio poprište bizantsko-bugarskih ratova.", "0d8b77bc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0923-11-19:0":{"b": ["Li Cunxu ušao je u Kaifeng: srušen je Kasni Liang", "aebaab18"], "d": ["Li Siyuan, prethodnica Li Cunxua koji je u Zhongduu razbio liangsku vojsku, u zoru je stigao do Fengqiuske kapije Kaifenga; liangski namjesnik Kaifenga Wang Zan predao je grad, a Li Cunxu ušao je u grad na Daliangsku kapiju.", "4ee60f2e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0934-01-01:0":{"b": ["Bizant je zauzeo Malatiju", "fd0898d0"], "d": ["Bizantska vojska pod zapovjedništvom domestika Istoka Ivana Kurkuasa napredovala je do Eufrata i 934. zauzela Malatiju; 943. zauzeti su i Majjafarikin, Amid, Dara i Nisibis.", "46c833cc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0943-01-01:0":{"b": ["Merzuban preuzima nadzor nad Azerbejdžanom, Aranom i Armenijom (330–331 / 942–943).", "fc600309"], "d": ["Merzuban preuzima nadzor nad Azerbejdžanom, Aranom i Armenijom (330–331 / 942–943).", "fc600309"]},
