"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0961-03-06:0":{"b": ["Pala je Kandija: Nikifor Foka povratio je Kretu", "aeefb280"], "d": ["Bizantske snage pod zapovjedništvom Nikifora Foke nakon jednogodišnje opsade 6. marta 961. zauzele su Kandiju; okončan je Kretski emirat koji je trajao oko 130 godina. Dio muslimanskog stanovništva napustio je ostrvo, a dio je prisiljen promijeniti vjeru.", "ec04c12b"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0962-01-01:0":{"b": ["Ahmed b. Hasan el-Kelbi nakon sedmomjesečne opsade zauzeo je bizantsku tvrđavu Taorminu i nazvao je Muizzija", "37e8ae59"], "d": ["Ahmed b. Hasan el-Kelbi nakon sedmomjesečne opsade zauzima bizantsku tvrđavu Taorminu i daje joj ime Muizzija.", "f8fcc7b1"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-01-01:0":{"b": ["Nikifor Foka okupirao je Misis i Tarsus (354/965).", "045053b4"], "d": ["Nikifor Foka okupirao je Misis i Tarsus (354/965).", "045053b4"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0965-08-16:0":{"b": ["Tarsus se predao Bizantu: Kilikija je došla pod bizantsku vlast", "b05e9bd3"], "d": ["Misis (Mopsuestija) predao se u julu 965., a Tarsus mjesec dana kasnije, 16. augusta 965., uz humane uvjete i ponovo postao kršćanski grad. Tako je oblast Kilikije pripojena Bizantu.", "faeb461f"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0969-10-28:0":{"b": ["Antiohija je pala u bizantske ruke", "ad0a5da3"], "d": ["Nakon što su bizantske vojske zauzele mnoge tvrđave i gradove u sjevernoj Siriji, Mihael Burcis i Petar Foka, koji su došli iz Kilikije, 28. oktobra 969. zauzeli su Antiohiju. Grad je oko 115 godina bio glavna bizantska baza u Siriji.", "38b840e3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0971-04-13:0":{"b": ["Cimiskije je na juriš zauzeo Veliki Preslav: istočna Bugarska pripojena je Bizantu", "07c84840"], "d": ["Ivan Cimiskije 12. aprila 971. ušao je u preslavsku ravnicu; uveče 13. aprila pao je bugarski glavni grad koji su branili Svjatoslavovi ljudi. Car Boris je zarobljen i bizantska uprava proširila se na Trakiju i istočnu Bugarsku.", "ae050b34"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0979-01-01:0":{"b": ["Azerbejdžan je pao u ruke Revvadida; Musafiridi su se povukli u Tarum (979. ili 980.)", "b5b0e767"], "d": ["Azerbejdžan je pao u ruke Revvadida; Musafiridi su se povukli u Tarum (979. ili 980.)", "b5b0e767"]},
